#if UNITY_EDITOR
using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using System.IO;using UnityEngine;
public sealed class DrpgPhase3Validation:MonoBehaviour {
 const BindingFlags F=BindingFlags.NonPublic|BindingFlags.Instance;DungeonPrototype world;DungeonSaveData original;List<string> results=new List<string>();
 public void Run(){StartCoroutine(Checks());}
 void Check(bool ok,string text){results.Add((ok?"PASS ":"FAIL ")+text);}
 object Call(string method,params object[] args){return typeof(DungeonPrototype).GetMethod(method,F).Invoke(world,args);}
 void Discover(Vector2Int cell){var grid=(bool[,])typeof(DungeonPrototype).GetField("explored",F).GetValue(world);grid[cell.x,cell.y]=true;}
 bool Has(string id,DungeonMapSymbol symbol){return world.VisibleMapMarkers().Exists(m=>m.id==id&&m.symbol==symbol);}
 IEnumerator WaitDoor(DungeonDoor door){float end=Time.realtimeSinceStartup+10;while(!door.IsOpen&&Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Checks(){world=UnityEngine.Object.FindFirstObjectByType<DungeonPrototype>();original=world.CaptureDungeonSave();bool enabled=world.enabled;world.enabled=false;
  try{
   var data=world.CaptureDungeonSave();data.introductionCompleted=true;world.RestoreDungeonSave(data);typeof(DungeonPrototype).GetField("startMenuOpen",F).SetValue(world,false);Time.timeScale=1;
   var map=DungeonMapSettings.Current;var chest=map.entities.objects.Find(e=>e.kind==DungeonEntityKind.Chest&&e.chestKind==DungeonChestKind.Normal&&string.IsNullOrEmpty(e.contentId));var door=map.entities.objects.Find(e=>e.kind==DungeonEntityKind.Door&&e.doorKind==DungeonDoorKind.Locked);var node=map.entities.objects.Find(e=>e.kind==DungeonEntityKind.Teleport);
   var grid=(bool[,])typeof(DungeonPrototype).GetField("explored",F).GetValue(world);grid[chest.cell.x,chest.cell.y]=false;Check(!world.VisibleMapMarkers().Exists(m=>m.id==chest.id),"Undiscovered chest hidden");Discover(chest.cell);Check(Has(chest.id,DungeonMapSymbol.ChestAvailable),"Discovered available chest shown");
   var states=(List<DungeonEntityState>)typeof(DungeonPrototype).GetField("mapEntityStates",F).GetValue(world);int count=states.Count;world.VisibleMapMarkers();Check(states.Count==count,"Rendering query creates no persistent state");
   world.StartCoroutine((IEnumerator)Call("OpenMapChest",chest));float end=Time.realtimeSinceStartup+10;while(!Has(chest.id,DungeonMapSymbol.ChestOpened)&&Time.realtimeSinceStartup<end)yield return null;Check(Has(chest.id,DungeonMapSymbol.ChestOpened),"Real chest animation updates opened symbol");
   Discover(door.cell);Check(Has(door.id,DungeonMapSymbol.DoorClosed),"Locked door shown closed");world.AcquireItem(door.requiredKeyId,1);Call("InteractMapEntity",door);var doors=(Dictionary<string,DungeonDoor>)typeof(DungeonPrototype).GetField("mapDoors",F).GetValue(world);yield return WaitDoor(doors[door.id]);Check(Has(door.id,DungeonMapSymbol.DoorOpen),"Key unlock and actual opening update door symbol");
   Discover(node.cell);var refuge=(RefugeProgress)typeof(DungeonPrototype).GetField("refuge",F).GetValue(world);refuge.unlockedNodes.Remove(node.id);Check(Has(node.id,DungeonMapSymbol.NodeLocked),"Inactive node has outline symbol");Call("ExamineMapNode",node);Check(Has(node.id,DungeonMapSymbol.NodeUnlocked),"Node activation immediately updates symbol");((WorldDialogue)typeof(DungeonPrototype).GetField("worldDialogue",F).GetValue(world)).Cancel();Call("CancelMapReveal");
   Discover(RefugeSettings.Current.saveCell);Check(Has("refuge.save",DungeonMapSymbol.Savepoint),"Legacy savepoint shown");var city=map.entities.objects.Find(e=>e.cityEntrance);grid[city.cell.x,city.cell.y]=false;Check(!world.VisibleMapMarkers().Exists(m=>m.id==city.id),"Undiscovered kingdom connection hidden");Discover(city.cell);Check(Has(city.id,DungeonMapSymbol.KingdomConnection),"Discovered kingdom connection shown");
   var previousMap=world.mapSettings;var preview=Instantiate(map);var previewObjects=Instantiate(map.entities);preview.entities=previewObjects;var connection=new DungeonMapEntity{id="test-map-connection",kind=DungeonEntityKind.Door,doorKind=DungeonDoorKind.Transition,destinationMap=Resources.Load<DungeonMapSettings>("DrpgPhase2Tests/FloorB"),cell=new Vector2Int(2,1),displayName="Otro piso"};previewObjects.objects.Add(connection);world.mapSettings=preview;Discover(connection.cell);Check(Has(connection.id,DungeonMapSymbol.FloorConnection),"Inter-floor destination has stairs symbol");world.mapSettings=previousMap;Destroy(previewObjects);Destroy(preview);
   Check(!world.MapCellVisited(chest.cell),"Discovery alone does not mark a visit");Call("WarpPlayer",new Vector2Int(2,1),0);Check(world.MapCellVisited(new Vector2Int(2,1)),"Actual arrival changes visited tile");
   data=world.CaptureDungeonSave();world.RestoreDungeonSave(data);Check(Has(chest.id,DungeonMapSymbol.ChestOpened),"Save restores opened chest symbol");Check(Has(door.id,DungeonMapSymbol.DoorOpen),"Save restores open door symbol");Check(Has(node.id,DungeonMapSymbol.NodeUnlocked),"Save restores unlocked node symbol");
   var mimic=map.entities.objects.Find(e=>e.chestKind==DungeonChestKind.Mimic&&e.kind==DungeonEntityKind.Chest);Discover(mimic.cell);var mimicState=(DungeonEntityState)Call("EntityState",mimic.id);mimicState.opened=true;Check(!world.VisibleMapMarkers().Exists(m=>m.id==mimic.id),"Removed Mimic does not leave a chest icon");
   var legacy=DungeonMapPersistence.Copy(original);legacy.version=1;legacy.activeMapId=null;legacy.maps=null;legacy.visited=null;world.RestoreDungeonSave(legacy);Check(world.MapCellVisited(legacy.cell),"Legacy save supports its known current visit");Check(world.VisibleMapMarkers().TrueForAll(m=>world.CaptureDungeonSave().explored.Contains(m.cell)),"Legacy markers remain discovery-gated");
   foreach(var size in new[]{4f,18f,32f,60f}){var tile=new Rect(10,20,size,size);var symbol=DungeonPrototype.MapSymbolRect(tile);Check(tile.Contains(symbol.min)&&tile.Contains(symbol.max)&&symbol.width<=22,"Symbol fits tile at "+size+" reference pixels");}
  }finally{world.RestoreDungeonSave(original);world.enabled=enabled;File.WriteAllLines("Tests/DrpgPhase3Results.txt",results);Debug.Log(string.Join("\n",results.ToArray()));}
 }
}
#endif
